pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - uint256 newVal: the value to pass to SetMinSum
    // - address caller: the actor that will call SetMinSum through the helper
    // We deploy a helper that forwards the call to c.SetMinSum but suppresses any revert by using a low-level call
    // The REF contract guarantees: once Initialized() is called, any call to SetMinSum must revert and therefore
    // MinSum must remain unchanged after such a call. The mutant may assign MinSum before the revert check
    // and a forwarding helper that swallows reverts can make MinSum observable changed — so we fuzz to find it.
    function testFuzz_property(uint256 newVal, address caller) public {
        // keep domain wide but avoid zero address for caller to be sensible
        if (caller == address(0)) caller = address(1);

        // initialize MinSum to some value via a normal call
        c.SetMinSum(123);
        // mark contract initialized
        c.Initialized();

        // record prior MinSum
        uint256 prior = c.MinSum();

        // deploy a forwarder that will call c.SetMinSum(newVal) from `caller`.
        // This forwarder uses a try/catch on the low-level call so the external EVM-level behavior
        // from the perspective of the test is that the forwarder call itself completes successfully
        // even if c.SetMinSum reverts internally. This distinguishes the mutant which assigns
        // before revert and thus may have changed state before the revert did not abort the external
        // observable execution of the forwarder.
        Forwarder f = new Forwarder(address(c));

        // fund caller so it can make calls (forwarder will use the provided caller via tx.origin)
        vm.deal(caller, 1 ether);

        // Have the forwarder perform the call as if initiated by `caller` using vm.prank.
        vm.prank(caller);
        // forwarder will invoke c.SetMinSum(newVal) internally
        bool ok = f.forwardSetMinSum(newVal);

        // EXACTLY ONE assertion: For the reference contract, since Initialized() was called,
        // any invocation of SetMinSum must revert and must not change MinSum. Thus after the
        // forwarder call (regardless of whether the forwarder suppressed the revert), c.MinSum()
        // must still equal the prior value. The buggy mutant can change MinSum for some inputs
        // (the fuzzer will find such a case), so this assertion will fail on the mutant.
        assertTrue(c.MinSum() == prior);
    }
}

// Helper forwarder that calls C.SetMinSum and swallows the revert so that the external call
// to the forwarder can still succeed even if the inner call reverted. This helps expose the
// mutant which assigns before checking and thus can leave changed state despite an overall
// observed successful external call.
contract Forwarder {
    C immutable target;
    constructor(address _t) { target = C(_t); }

    // returns true if the low-level call to target succeeded, false if it reverted
    // but the function itself does not revert, so the test can observe state after.
    function forwardSetMinSum(uint256 _v) external returns (bool ok) {
        (ok, ) = address(target).call(abi.encodeWithSignature("SetMinSum(uint256)", _v));
    }
}

